import{_ as e,o,c as a,a2 as i}from"./chunks/framework.lxr64Vqo.js";const c=JSON.parse('{"title":"🍿 Stremio & Nuvio Setup","description":"","frontmatter":{},"headers":[],"relativePath":"clients/stremio-nuvio.md","filePath":"clients/stremio-nuvio.md","lastUpdated":1795112636000}'),s={name:"clients/stremio-nuvio.md"};function r(n,t,l,d,u,h){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="🍿-stremio-nuvio-setup" tabindex="-1">🍿 Stremio &amp; Nuvio Setup <a class="header-anchor" href="#🍿-stremio-nuvio-setup" aria-label="Permalink to &quot;🍿 Stremio &amp; Nuvio Setup&quot;">​</a></h1><p>NoxMedia implements the official <strong>Stremio Addon v3 Protocol</strong>, allowing you to integrate your Telegram libraries and AI custom catalogs into <a href="https://stremio.com" target="_blank" rel="noreferrer">Stremio</a> and <a href="https://github.com/nuvio-app" target="_blank" rel="noreferrer">Nuvio</a>.</p><hr><h2 id="🚀-quick-setup-for-stremio" tabindex="-1">🚀 Quick Setup for Stremio <a class="header-anchor" href="#🚀-quick-setup-for-stremio" aria-label="Permalink to &quot;🚀 Quick Setup for Stremio&quot;">​</a></h2><h3 id="_1-get-your-manifest-url" tabindex="-1">1. Get Your Manifest URL <a class="header-anchor" href="#_1-get-your-manifest-url" aria-label="Permalink to &quot;1. Get Your Manifest URL&quot;">​</a></h3><p>Ensure your NoxMedia server is running. Your Stremio manifest URL is:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://&lt;YOUR_SERVER_IP&gt;:8096/manifest.json</span></span></code></pre></div><p><em>(e.g., <code>http://192.168.1.15:8096/manifest.json</code> or <code>http://127.0.0.1:8096/manifest.json</code> if running locally on the same Android TV / phone).</em></p><h3 id="_2-install-addon-in-stremio" tabindex="-1">2. Install Addon in Stremio <a class="header-anchor" href="#_2-install-addon-in-stremio" aria-label="Permalink to &quot;2. Install Addon in Stremio&quot;">​</a></h3><ol><li>Open <strong>Stremio</strong> on your PC, Android TV, Mobile, or Web.</li><li>Click the <strong>Addons</strong> puzzle icon (🧩).</li><li>In the search box or address bar, paste your full manifest URL:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.1.15:8096/manifest.json</span></span></code></pre></div></li><li>Click <strong>Install</strong>.</li><li>NoxMedia will now appear under your installed Community Addons.</li></ol><hr><h2 id="🌟-nuvio-setup" tabindex="-1">🌟 Nuvio Setup <a class="header-anchor" href="#🌟-nuvio-setup" aria-label="Permalink to &quot;🌟 Nuvio Setup&quot;">​</a></h2><p><a href="https://github.com/nuvio-app" target="_blank" rel="noreferrer">Nuvio</a> is a modern, lightweight streaming client designed for seamless metadata exploration.</p><ol><li>Open <strong>Nuvio</strong> settings.</li><li>Go to <strong>Providers / Addons</strong> → <strong>Add Custom Provider</strong>.</li><li>Paste <code>http://&lt;YOUR_SERVER_IP&gt;:8096/manifest.json</code>.</li><li>Tap <strong>Connect</strong>.</li><li>Your custom shelves and Telegram channels will immediately populate the home feed.</li></ol><hr><h2 id="🎯-what-you-get" tabindex="-1">🎯 What You Get <a class="header-anchor" href="#🎯-what-you-get" aria-label="Permalink to &quot;🎯 What You Get&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:center;">Support</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Catalog Exploration</strong></td><td style="text-align:center;">✅</td><td style="text-align:left;">Default Movies, Series, Anime + All Custom AI Shelves</td></tr><tr><td style="text-align:left;"><strong>Rich Metadata</strong></td><td style="text-align:center;">✅</td><td style="text-align:left;">TMDB synopses, cast, ratings, and high-res posters</td></tr><tr><td style="text-align:left;"><strong>Stream Resolving</strong></td><td style="text-align:center;">✅</td><td style="text-align:left;">Direct HTTP streaming without local disk caching</td></tr><tr><td style="text-align:left;"><strong>Multiple Audio / Subtitles</strong></td><td style="text-align:center;">✅</td><td style="text-align:left;">Embedded tracks detected and passed directly to the player</td></tr><tr><td style="text-align:left;"><strong>Multi-Quality Sources</strong></td><td style="text-align:center;">✅</td><td style="text-align:left;">1080p, 4K, 720p stream selector dialogs</td></tr></tbody></table><hr><h2 id="💡-pro-tips" tabindex="-1">💡 Pro Tips <a class="header-anchor" href="#💡-pro-tips" aria-label="Permalink to &quot;💡 Pro Tips&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Android TV Stremio Experience</strong>: For the smoothest 4K HDR playback on Android TV boxes (such as Chromecast with Google TV or Xiaomi Box), set Stremio&#39;s default player to <strong>ExoPlayer</strong> with <strong>Hardware Acceleration</strong> turned on in settings.</p></div>',20)])])}const g=e(s,[["render",r]]);export{c as __pageData,g as default};
